from pathlib import Path
from html.parser import HTMLParser
class P(HTMLParser):
 def __init__(self):super().__init__();self.skip=0
 def handle_starttag(self,t,a):
  if t in ('script','style'):self.skip+=1
  if t in ('input','textarea','select','form'):print(t,dict(a))
  if t=='a':
   for k,v in a:
    if k=='href' and v.startswith('mailto:'):print('MAIL',v)
 def handle_endtag(self,t):
  if t in ('script','style'):self.skip=max(0,self.skip-1)
 def handle_data(self,d):
  if not self.skip and d.strip():print(d.strip())
p=P();p.feed(Path('products/services/first-receipt/agency-route/pointer-contact.html').read_text())
